	data, err := os.ReadFile("logs.txt")
	if err != nil {
		return c.Status(fiber.StatusInternalServerError).SendString("An error occurred")
	}

	return c.Type("text/plain").Send(data)
}

func main() {
	app := fiber.New()

	app.Post("/log", logMessageHandler)
	app.Get("/logs", getLogsHandler)

