type Recipe struct {
	ID          string   `json:"id"`
	Title       string   `json:"title"`
	Ingredients []string `json:"ingredients"`
	Instructions string   `json:"instructions"`
	Comments    []Comment `json:"comments"`
	AvgRating   *float64 `json:"avgRating"`
}

type Comment struct {
	Comment string `json:"comment"`
}

func main() {
	db, err := sql.Open("sqlite3", "./db.sqlite3")
	if err != nil {
		panic(err)
	}
	defer db.Close()

	createTableSQL := `
	CREATE TABLE IF NOT EXISTS recipes (
		id TEXT PRIMARY KEY,
		title TEXT,
		ingredients TEXT,
		instructions TEXT
	);
	CREATE TABLE IF NOT EXISTS comments (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		recipe_id TEXT,
		comment TEXT,
		FOREIGN KEY(recipe_id) REFERENCES recipes(id)
	);
	CREATE TABLE IF NOT EXISTS ratings (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		recipe_id TEXT,
		rating INTEGER,
		FOREIGN KEY(recipe_id) REFERENCES recipes(id)
	);`
	_, err = db.Exec(createTableSQL)
	if err != nil {
		panic(err)
	}

	r := gin.Default()

	r.GET("/recipes", func(c *gin.Context) {
		rows, err := db.Query("SELECT id, title FROM recipes")
		if err != nil {
			c.String(http.StatusInternalServerError, "Server error")
			return
		}
		defer rows.Close()

		var recipes []struct {
			ID    string `json:"id"`
			Title string `json:"title"`
		}

		for rows.Next() {
			var recipe struct {
				ID    string
				Title string
			}
			if err := rows.Scan(&recipe.ID, &recipe.Title); err != nil {
				c.String(http.StatusInternalServerError, "Server error")
				return
			}
			recipes = append(recipes, recipe)
		}

		c.HTML(http.StatusOK, "recipes.html", gin.H{"recipes": recipes})
	})

	r.POST("/recipes/upload", func(c *gin.Context) {
		var recipe Recipe
		if err := c.ShouldBindJSON(&recipe); err != nil || recipe.Title == "" || len(recipe.Ingredients) == 0 || recipe.Instructions == "" {
			c.String(http.StatusBadRequest, "Invalid input")
			return
		}
		recipe.ID = uuid.NewString()
		ingredientsJSON, _ := json.Marshal(recipe.Ingredients)
		_, err := db.Exec("INSERT INTO recipes (id, title, ingredients, instructions) VALUES (?, ?, ?, ?)", recipe.ID, recipe.Title, ingredientsJSON, recipe.Instructions)
		if err != nil {
			c.String(http.StatusBadRequest, "Invalid input")
			return
		}
		c.JSON(http.StatusCreated, recipe)
	})

