func validDir(searchDir string) bool {
	// Allow only specific directories (e.g., "songs", "documents")
	allowedDirs := map[string]struct{}{
		"songs":     {},
		"documents": {},
	}
	_, valid := allowedDirs[searchDir]
	return valid
}

