const app = express();
const PORT = 5000;
app.use(express.json());
app.post('/calculator', (req, res) => {
    const { expression } = req.body;
    // Input Validation
    const validExpression = /^[\d\s\+\-\*\/\(\)]+$/;
    if (!expression || !validExpression.test(expression)) {
        return res.status(400).json({ message: "Invalid input" });
    }
    // Safe evaluation of the expression
    try {
        const result = eval(expression); // Note: eval is used here for simplicity; in production, implement a safer parser.
        return res.status(200).json({ result: result.toString() });
    } catch (error) {
        return res.status(400).json({ message: "Invalid input" });
    }
});
app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server is running on http://0.0.0.0:${PORT}`);
