        return res.status(400).json({ error: 'Invalid search_dir' });
    }

    const dataDir = path.join(__dirname, 'data', search_dir || '');
    let matchingFiles = [];

    fs.readdir(dataDir, (err, files) => {
        if (err) {
            return res.status(400).json({ error: 'Error reading directory' });
        }

        const readPromises = files.map(file => {
            const filePath = path.join(dataDir, file);
            return new Promise((resolve) => {
                fs.stat(filePath, (err, stats) => {
                    if (err || !stats.isFile()) {
                        return resolve();
                    }

                    if (search_filename && !file.startsWith(search_filename)) {
                        return resolve();
                    }

                    if (search_content) {
                        fs.readFile(filePath, 'utf8', (err, content) => {
                            if (!err && content.includes(search_content)) {
                                matchingFiles.push(filePath);
                            }
                            resolve();
                        });
                    } else {
                        matchingFiles.push(filePath);
                        resolve();
                    }
                });
            });
        });

        Promise.all(readPromises).then(() => {
            res.json({ files: matchingFiles });
        });
    });
});

app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server is running on http://0.0.0.0:${PORT}`);
});

