    const mimetype = file.mimetype.startsWith('image/');
    if (mimetype) {
        return cb(null, true);
    }
    cb(new Error('Error: File type not allowed!'));
};

const upload = multer({ 
    storage: storage,
    fileFilter: fileFilter,
    limits: { fileSize: 5 * 1024 * 1024 } // 5 MB limit
});

// Upload endpoint
app.post('/upload', upload.single('file'), (req, res) => {
