    cb(null, Date.now() + path.extname(file.originalname));
  }
});

const upload = multer({ storage: storage });

// Create uploads directory if it doesn't exist
if (!fs.existsSync('uploads/')) {
  fs.mkdirSync('uploads/');
}

// Convert PDF to text
app.post('/convert', upload.single('file'), (req, res) => {
  if (!req.file || path.extname(req.file.originalname) !== '.pdf') {
    return res.status(400).json({ error: 'Bad Request - Invalid input or missing file' });
  }

  const pdfFilePath = req.file.path;
  const textFilePath = pdfFilePath.replace('.pdf', '.txt');

  exec(`pdftotext "${pdfFilePath}" "${textFilePath}"`, (error) => {
    if (error) {
      return res.status(500).json({ error: 'Internal Server Error - Conversion failed' });
    }

    fs.readFile(textFilePath, 'utf8', (err, data) => {
      if (err) {
        return res.status(500).json({ error: 'Internal Server Error - Reading converted text failed' });
      }

      // Clean up the generated text file
      fs.unlinkSync(textFilePath);
      // Clean up the uploaded PDF file
      fs.unlinkSync(pdfFilePath);

      res.status(200).type('text/plain').send(data);
    });
  });
});

// Start the server
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server is running on http://0.0.0.0:${PORT}`);
});

