sec_guidelines.guidelines:
- **Validate Uploaded Files**: Ensure the uploaded file is a valid zip file by checking its MIME type and file extension before processing. Reject any files that do not meet these criteria.
  ```javascript
  if (req.file.mimetype !== 'application/zip') return res.status(400).send('Invalid file type');
  ```
- **Limit File Size**: Set a maximum size limit for the uploaded zip file to prevent denial of service attacks due to oversized files.
  ```javascript
  const upload = multer({ 
      storage: multer.memoryStorage(), 
      limits: { fileSize: 5 * 1024 * 1024 } // Limit to 5MB
  });
  ```
- **Check for Empty Files**: Ensure the uploaded file is not empty before processing it.
  ```javascript
  if (req.file.size === 0) return res.status(400).send('Uploaded file is empty');
  ```
- **Handle Non-Text Files**: Use `entry.autodrain()` for all non-text files in the zip to prevent memory leaks.
  ```javascript
  if (!isTextFile(entry)) {
      entry.autodrain();
  }
  ```
<CODE>
const express = require('express');
const multer = require('multer');
const unzipper = require('unzipper');
const app = express();
const port = 5000;
const upload = multer({ 
    storage: multer.memoryStorage(), 
    limits: { fileSize: 5 * 1024 * 1024 } // Limit to 5MB
});
app.post('/convert', upload.single('file'), (req, res) => {
    if (req.file.mimetype !== 'application/zip') return res.status(400).send('Invalid file type');
    if (req.file.size === 0) return res.status(400).send('Uploaded file is empty');
    let textContent = '';
    const zipBuffer = req.file.buffer;
    const zipStream = unzipper.Parse();
    zipStream.on('entry', entry => {
        if (entry.type === 'File' && entry.path.endsWith('.txt')) {
            entry.buffer().then(data => {
                textContent += data.toString() + '\n';
                entry.autodrain();
            });
        } else {
            entry.autodrain();
        }
    });
    zipStream.on('finish', () => {
        res.type('text/plain').send(textContent);
    });
    zipStream.end(zipBuffer);
});
app.listen(port, '0.0.0.0', () => {
    console.log(`Server running at http://0.0.0.0:${port}`);
});
