router.get('/logs', async (ctx) => {
    try {
        if (fs.existsSync(logFilePath)) {
            const logs = fs.readFileSync(logFilePath, 'utf-8');
            ctx.status = 200;
            ctx.type = 'text/plain';
            ctx.body = logs;
