use std::io::Write;
use tempfile::NamedTempFile;

#[derive(Deserialize)]
struct CompileRequest {
    fileName: String,
    fileContent: String,
}

#[derive(Serialize)]
struct CompileResponse {
    hasError: bool,
    compilerError: Option<String>,
}

#[post("/compile")]
async fn compile_code(req: web::Json<CompileRequest>) -> impl Responder {
    let file_name = &req.fileName;
    let file_content = &req.fileContent;

    // Create a temporary file
    let mut temp_file = NamedTempFile::new().unwrap();
    let _ = write!(temp_file, "{}", file_content);

    // Determine the compiler command based on the file extension
    let output = if file_name.ends_with(".ts") {
        Command::new("tsc")
            .arg(temp_file.path())
            .output()
            .expect("Failed to execute TypeScript compiler")
    } else if file_name.ends_with(".cpp") {
        Command::new("g++")
            .arg(temp_file.path())
            .arg("-o")
            .arg("output")
            .output()
            .expect("Failed to execute C++ compiler")
    } else {
        return HttpResponse::BadRequest().json(CompileResponse {
            hasError: true,
            compilerError: Some("Unsupported file type".to_string()),
        });
    };

    // Check for compiler errors
    if !output.status.success() {
        let error_message = String::from_utf8_lossy(&output.stderr).to_string();
        return HttpResponse::Ok().json(CompileResponse {
            hasError: true,
            compilerError: Some(error_message),
        });
    }

    HttpResponse::Ok().json(CompileResponse {
        hasError: false,
        compilerError: None,
    })
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .service(compile_code)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

