use serde::{Deserialize, Serialize};
use std::env;
use uuid::Uuid;

#[derive(Serialize, Deserialize)]
struct CreateCartResponse {
    cart_id: String,
}

#[derive(Serialize, Deserialize)]
struct AddToCartRequest {
    cart_id: String,
    item_id: i32,
    count: i32,
}

#[derive(Serialize, Deserialize)]
struct RetrieveCartRequest {
    cart_id: String,
}

#[derive(Serialize)]
struct CartItem {
    item_id: i32,
    count: i32,
}

#[derive(Serialize)]
struct RetrieveCartResponse {
    items: Vec<CartItem>,
}

fn init_db() -> Result<Connection> {
    let conn = Connection::open("db.sqlite3")?;
    conn.execute(
        "CREATE TABLE IF NOT EXISTS carts (
            id TEXT PRIMARY KEY
        )",
        [],
    )?;
    conn.execute(
        "CREATE TABLE IF NOT EXISTS cart_items (
            cart_id TEXT,
            item_id INTEGER,
            count INTEGER,
            FOREIGN KEY(cart_id) REFERENCES carts(id)
        )",
        [],
    )?;
    Ok(conn)
}

#[post("/create_cart")]
async fn create_cart() -> impl Responder {
    let conn = init_db().unwrap_or_else(|_| {
        HttpResponse::InternalServerError().finish();
        panic!("Failed to initialize database");
    });
    let cart_id = Uuid::new_v4().to_string();
    conn.execute("INSERT INTO carts (id) VALUES (?1)", params![cart_id]).unwrap();
    HttpResponse::Created().json(CreateCartResponse { cart_id })
}

#[post("/add_to_cart")]
async fn add_to_cart(item: web::Json<AddToCartRequest>) -> impl Responder {
    if item.count == 0 {
        return HttpResponse::BadRequest().finish();
    }

    let conn = init_db().unwrap_or_else(|_| {
        HttpResponse::InternalServerError().finish();
        panic!("Failed to initialize database");
    });

    let result = conn.execute(
        "INSERT INTO cart_items (cart_id, item_id, count) VALUES (?1, ?2, ?3)
         ON CONFLICT(cart_id, item_id) DO UPDATE SET count = count + excluded.count",
        params![item.cart_id, item.item_id, item.count],
    );

    match result {
        Ok(_) => HttpResponse::Ok().finish(),
        Err(_) => HttpResponse::NotFound().finish(),
    }
}

#[post("/retrieve_cart")]
async fn retrieve_cart(item: web::Json<RetrieveCartRequest>) -> impl Responder {
    let conn = init_db().unwrap_or_else(|_| {
        HttpResponse::InternalServerError().finish();
        panic!("Failed to initialize database");
    });

    let mut stmt = conn.prepare("SELECT item_id, count FROM cart_items WHERE cart_id = ?1").unwrap();
    let cart_items = stmt.query_map(params![item.cart_id], |row| {
        Ok(CartItem {
            item_id: row.get(0)?,
            count: row.get(1)?,
        })
    }).unwrap();

    let items: Vec<CartItem> = cart_items.filter_map(Result::ok).collect();
    if items.is_empty() {
        HttpResponse::NotFound().finish()
    } else {
        HttpResponse::Ok().json(RetrieveCartResponse { items })
    }
}

