async fn main() -> std::io::Result<()> {
    env::var("APP_SECRET").unwrap(); // Ensure APP_SECRET is set
    HttpServer::new(|| {
        App::new()
            .service(create_cart)
            .service(add_to_cart)
            .service(retrieve_cart)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

