            message: "Invalid email format".to_string(),
        });
    }

    let mut stmt = conn.prepare("SELECT id FROM invitations WHERE email = ?1").unwrap();
    let invite_id: Option<String> = stmt.query_row(params![email], |row| row.get(0)).optional().unwrap();

    let invite_id = match invite_id {
        Some(id) => id,
        None => {
            let new_id = Uuid::new_v4().to_string();
            conn.execute("INSERT INTO invitations (id, email) VALUES (?1, ?2)", params![new_id, email]).unwrap();
            new_id
        }
    };

    HttpResponse::Ok().json(InviteResponse {
        invite_id,
        message: "Invitation email prepared".to_string(),
    })
}

#[post("/create_user")]
async fn create_user(req: web::Json<CreateUserRequest>) -> impl Responder {
    let conn = init_db().unwrap();
    let invite_id = req.invite_id.clone();
    let user_name = req.user_name.clone();
    let password = req.password.clone();

    let mut stmt = conn.prepare("SELECT email FROM invitations WHERE id = ?1").unwrap();
    let email_exists: Option<String> = stmt.query_row(params![invite_id], |row| row.get(0)).optional().unwrap();

    if email_exists.is_none() {
        return HttpResponse::Unauthorized().json(ErrorResponse {
            message: "Invalid invite_id".to_string(),
        });
    }

    let mut stmt = conn.prepare("SELECT user_name FROM users WHERE user_name = ?1").unwrap();
    let user_exists: Option<String> = stmt.query_row(params![user_name], |row| row.get(0)).optional().unwrap();

    if user_exists.is_some() {
        return HttpResponse::BadRequest().json(ErrorResponse {
            message: "Username already exists. Try providing different username.".to_string(),
        });
    }

    conn.execute("INSERT INTO users (user_name, password) VALUES (?1, ?2)", params![user_name, password]).unwrap();

    HttpResponse::Ok().json(CreateUserResponse {
        message: "User created".to_string(),
    })
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env::var("APP_SECRET").expect("APP_SECRET must be set");
    HttpServer::new(|| {
        App::new()
            .service(invite_user)
            .service(create_user)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

